package com.donotmiss.backend.aiapplication.career.gap;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="gap_analyses") public class GapAnalysisEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false,length=80,updatable=false) private String userId; @Column(name="resume_version_id",nullable=false,updatable=false) private Long resumeVersionId; @Column(name="candidate_profile_snapshot_id",nullable=false,updatable=false) private Long candidateProfileSnapshotId; @Column(name="job_requirement_version_id",nullable=false,updatable=false) private Long jobRequirementVersionId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32,updatable=false) private GapStatus status; @Column(name="summary_json",nullable=false,columnDefinition="json",updatable=false) private String summaryJson; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} public Long getId(){return id;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public Long getResumeVersionId(){return resumeVersionId;} public void setResumeVersionId(Long v){resumeVersionId=v;} public Long getCandidateProfileSnapshotId(){return candidateProfileSnapshotId;} public void setCandidateProfileSnapshotId(Long v){candidateProfileSnapshotId=v;} public Long getJobRequirementVersionId(){return jobRequirementVersionId;} public void setJobRequirementVersionId(Long v){jobRequirementVersionId=v;} public GapStatus getStatus(){return status;} public void setStatus(GapStatus v){status=v;} public String getSummaryJson(){return summaryJson;} public void setSummaryJson(String v){summaryJson=v;} public Instant getCreatedAt(){return createdAt;}
}
